import { useState } from "react";

function PostForm({ token, onPostAdded, categoryId }) {
    const [title, setTitle] = useState("");
    const [content, setContent] = useState("");
    const [error, setError] = useState("");
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!title || !content) {
            setError("Заповніть всі поля");
            return;
        }

        setLoading(true);
        try {
            const res = await fetch("http://localhost:5000/api/posts", {
                method: "POST",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${token}`,
                },
                body: JSON.stringify({
                    title,
                    content,
                    category_id: categoryId || 1 // якщо категорія не вибрана, дефолт 1
                }),
            });

            const data = await res.json();

            if (!res.ok) {
                setError(data.message || "Помилка при створенні поста");
            } else {
                setTitle("");
                setContent("");
                setError("");
                if (onPostAdded) onPostAdded(); // оновлюємо список постів
            }
        } catch (err) {
            console.error(err);
            setError("Помилка при запиті до сервера");
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="card-gradient rounded-2xl p-6 shadow-xl">
            <div className="flex items-center mb-6">
                <div className="w-10 h-10 bg-gradient-to-br from-primary-500 to-accent-500 rounded-lg flex items-center justify-center mr-3 shadow-lg">
                    <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                    </svg>
                </div>
                <h3 className="text-xl font-bold gradient-text">Створити пост</h3>
            </div>

            {error && (
                <div className="mb-4 p-3 bg-red-50 border-l-4 border-red-500 rounded-lg">
                    <p className="text-red-700 text-sm font-medium">{error}</p>
                </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-4">
                <input
                    type="text"
                    placeholder="Заголовок поста..."
                    value={title}
                    onChange={(e) => setTitle(e.target.value)}
                    className="input-field w-full p-3 border border-gray-300 rounded-lg"
                />
                <textarea
                    placeholder="Що у вас на думці?..."
                    value={content}
                    onChange={(e) => setContent(e.target.value)}
                    rows={4}
                    className="input-field w-full p-3 border border-gray-300 rounded-lg resize-none"
                />
                <button
                    type="submit"
                    disabled={loading}
                    className="btn-primary w-full bg-gradient-to-r from-primary-500 to-accent-500 text-white font-semibold py-2 rounded-lg hover:shadow-lg disabled:opacity-50 disabled:cursor-not-allowed"
                >
                    {loading ? "Публікуємо..." : "Опублікувати"}
                </button>
            </form>
        </div>
    );
}

export default PostForm;
